-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.card_states_of_decks(p_deck_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if p_deck_ids is null or cardinality(p_deck_ids) > 5000 then
    raise exception 'too_large' using errcode = '22023';
  end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(c) - 'user_id' order by c.note_guid, c.ord), '[]'::jsonb)
      from public.card_states c
     where c.user_id = (select auth.uid()) and c.deck_id = any (p_deck_ids)
  );
end;
$function$;

grant execute on function public.card_states_of_decks(p_deck_ids text[]) to authenticated;
grant execute on function public.card_states_of_decks(p_deck_ids text[]) to service_role;
